/* Exam Ready Notes — Service Worker for Web Push notifications.
   This file must sit in the SAME folder as index.html (site root, or the
   folder that covers the scope you want push notifications to work in). */

const DEFAULT_ICON = 'data:image/png;base64,';

self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener('push', (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch (e) {
    data = { title: 'Exam Ready Notes', body: event.data ? event.data.text() : '' };
  }

  const title = data.title || 'Exam Ready Notes';
  const options = {
    body: data.body || '',
    icon: data.icon || DEFAULT_ICON,
    badge: data.badge || DEFAULT_ICON,
    data: { url: data.url || '/' },
    vibrate: [100, 50, 100],
    tag: data.tag || 'exam-ready-notes',
    renotify: true
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url = (event.notification.data && event.notification.data.url) || '/';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if (client.url.includes(self.location.origin) && 'focus' in client) {
          return client.focus();
        }
      }
      if (self.clients.openWindow) return self.clients.openWindow(url);
    })
  );
});
